'use client';

import { type ChangeEvent, FormEvent, useEffect, useState } from 'react';
import { CREATABLE_ACTIVITY_TYPES, type ActivityType } from '@/lib/activity-types';
import type { SourceKind } from '@/lib/source-ingestion';
import { COURSE_IMAGE_STYLE_LABELS, COURSE_IMAGE_STYLES } from '@/lib/course-images';
import type { CourseLength } from '@/lib/course-pages';
import { DEFAULT_EXTERNAL_GAME_CONTENT, externalResourceEmbedUrl, extractExternalGameUrl, inspectExternalHtml, providerFromExternalGameUrl, providerLabel, type ExternalGameContent, type ExternalResourceOutput } from '@/lib/external-games';

type ApiEnvelope<T> = { ok: true; data: T } | { ok: false; error: { message: string } };
const SOURCE_OPTIONS: Array<{ id:SourceKind; icon:string; title:string; copy:string }> = [
  {id:'prompt',icon:'✦',title:'Avec un prompt',copy:'Décrivez le cours souhaité'},
  {id:'youtube',icon:'▶',title:'Avec une vidéo',copy:'YouTube, Vimeo ou média direct'},
  {id:'documents',icon:'▤',title:'Avec un PDF',copy:'PDF, Word, texte ou images'},
  {id:'web',icon:'↗',title:'Avec un lien web',copy:'Page et sources extérieures'},
  {id:'external',icon:'⌁',title:'Avec une activité externe',copy:'Wordwall, Genially, LearningApps, Canva…'},
];
type LibraryDocument = { id:string;originalName:string;mimeType:string;status:'uploaded'|'validating'|'extracting'|'analyzing'|'indexed'|'ready'|'failed';pageCount:number|null;detectedTheme:string|null;summary:string|null };
type GeneratedCoursePage = {id:string;title:string;kind:'cover'|'introduction'|'chapter'|'synthesis'|'exercises';lead:string};
type ScenarioBrief = { title:string;theme:string;subtheme:string;audience:string;profession:string;level:'debutant'|'intermediaire'|'avance';prerequisites:string[];durationMinutes:number;objectives:string[];competencies:string[];vocabulary:string[];professionalContext:string;learnerRole:string;learningGoal:string;constraints:string[];risks:string[];keyProcedures:string[];successCriteria:string[];recommendedSceneCount:number;recommendedDifficulty:'simple'|'progressive'|'complexe' };
type ExternalAnalysis = { title:string;theme:string;audience:string;level:'debutant'|'intermediaire'|'avance';difficulty:string;objectives:string[];instructions:string;concepts:string[];introduction:string;preGameExplanation:string;learnerTips:string[];debrief:string;correction:string;summary:string;memo:string;questions:Array<{question:string;answer:string}>;scenario:{title:string;context:string;aiRole:string;learnerRole:string;mission:string;prompts:string[]} };
const EXTERNAL_OUTPUT_OPTIONS: Array<[ExternalResourceOutput,string]> = [['course','Cours complet'],['summary','Résumé'],['memo','Fiche mémo'],['explanations','Explications pédagogiques'],['quiz','Quiz'],['true-false','Vrai ou faux'],['open-questions','Questions ouvertes'],['scenario','Mise en situation'],['case-study','Étude de cas'],['exercise','Exercice complémentaire'],['correction','Corrigé'],['pdf','Version PDF']];
const IMAGE_KIND_OPTIONS = [
  ['automatic','Génération automatique des visuels utiles'],['cover','Image de couverture'],['realistic','Images réalistes'],['illustration','Illustrations pédagogiques'],['diagram','Schémas explicatifs'],['example','Images pour les exemples'],['exercise','Images pour les exercices et les quiz'],
] as const;
export type AiStudioDefaults = {prompt?:string;fileIds?:string[];contextLabel?:string;mainFolderId?:string};

export function AiStudioDialog({ onClose,onCreated,defaults }: { onClose: () => void; onCreated: (message: string) => void; defaults?:AiStudioDefaults|null }) {
  const [sourceKind,setSourceKind] = useState<SourceKind>(defaults?.fileIds?.length?'documents':'prompt'); const [formats,setFormats] = useState<ActivityType[]>(['quiz']); const [files,setFiles] = useState<File[]>([]);
  const [createActivity,setCreateActivity] = useState(true); const [createPresentation,setCreatePresentation] = useState(false); const [busy,setBusy] = useState(false); const [progress,setProgress] = useState(''); const [error,setError] = useState('');
  const [library,setLibrary] = useState<LibraryDocument[]>([]); const [selectedFileIds,setSelectedFileIds] = useState<string[]>(defaults?.fileIds??[]); const [uploadedFileIds,setUploadedFileIds] = useState<string[]>([]); const [scenarioBrief,setScenarioBrief] = useState<ScenarioBrief | null>(null); const [projectId,setProjectId] = useState(''); const [scenarioCount,setScenarioCount] = useState(4);
  const [courseLength,setCourseLength]=useState<CourseLength>('intermediate'); const [customPageCount,setCustomPageCount]=useState(8); const [analyzedFileIds,setAnalyzedFileIds]=useState<string[]>([]);
  const [addImages,setAddImages]=useState(true); const [autoValidateImages,setAutoValidateImages]=useState(true); const [imageSource,setImageSource]=useState<'upload'|'ai'|'document'>('ai'); const [imageFile,setImageFile]=useState<File|null>(null); const [imageOperation,setImageOperation]=useState<'document-use'|'document-crop'|'document-inspired'>('document-inspired'); const [imageRights,setImageRights]=useState(false); const [imageKinds,setImageKinds]=useState<string[]>(['automatic']);
  const [externalResource,setExternalResource]=useState<ExternalGameContent>(()=>JSON.parse(JSON.stringify(DEFAULT_EXTERNAL_GAME_CONTENT)) as ExternalGameContent); const [externalRaw,setExternalRaw]=useState(''); const [externalInputMode,setExternalInputMode]=useState<'link'|'iframe'|'html'>('link'); const [externalError,setExternalError]=useState(''); const [externalAnalysis,setExternalAnalysis]=useState<ExternalAnalysis|null>(null); const [externalFiles,setExternalFiles]=useState<File[]>([]); const [externalAnalyzing,setExternalAnalyzing]=useState(false); const [externalMessage,setExternalMessage]=useState('');
  useEffect(() => { apiJson<{files:LibraryDocument[]}>('/api/files').then((result) => setLibrary(result.files)).catch(() => setLibrary([])); },[]);

  const resetPreparation = () => { setScenarioBrief(null); setProjectId(''); };
  const updateExternalAnalysis=(patch:Partial<ExternalAnalysis>)=>setExternalAnalysis((current)=>current?{...current,...patch}:current);

  const acceptExternalInput=(value:string)=>{setExternalRaw(value);setExternalAnalysis(null);setExternalMessage('');const url=extractExternalGameUrl(value);if(!value.trim()){setExternalError('');setExternalResource((current)=>({...current,sourceUrl:'',embedUrl:'',htmlSourceName:''}));return;}if(!url){setExternalError('Seuls un lien HTTPS public ou un iframe contenant une adresse HTTPS sont acceptés.');setExternalResource((current)=>({...current,sourceUrl:'',embedUrl:'',htmlSourceName:''}));return;}setExternalError('');setExternalResource((current)=>({...current,sourceUrl:url,embedUrl:externalResourceEmbedUrl(url),provider:providerFromExternalGameUrl(url),htmlSourceName:''}));};
  const importExternalHtml=async(event:ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;setExternalAnalysis(null);setExternalMessage('');setExternalError('');try{if(!/\.html?$/i.test(file.name)&&file.type!=='text/html')throw new Error('Choisissez un fichier HTML au format .html ou .htm.');if(!file.size)throw new Error('Le fichier HTML est vide.');if(file.size>2_000_000)throw new Error('Le fichier HTML dépasse la limite de 2 Mo.');const inspected=inspectExternalHtml(await file.text());if(!inspected)throw new Error('Aucun lien HTTPS intégrable n’a été détecté dans ce fichier. Collez le lien public du jeu ou son code iframe.');const context=[inspected.title?`Titre détecté dans le fichier HTML : ${inspected.title}`:'',inspected.readableText].filter(Boolean).join('\n\n');setExternalRaw(inspected.sourceUrl);setExternalResource((current)=>({...current,sourceUrl:inspected.sourceUrl,embedUrl:inspected.embedUrl,provider:inspected.provider,htmlSourceName:file.name,supportText:[current.supportText,context].filter(Boolean).join('\n\n').slice(0,60_000)}));setExternalMessage(`Le fichier « ${file.name} » a été nettoyé. Seuls le lien HTTPS et le texte utile seront analysés.`);}catch(reason){setExternalError(reason instanceof Error?reason.message:'Lecture du fichier HTML impossible.');}};
  const analyzeExternal=async()=>{setExternalAnalyzing(true);setExternalError('');setExternalMessage('');try{let supportFileIds=externalResource.supportFileIds;if(externalFiles.length){const form=new FormData();externalFiles.forEach((file)=>form.append('files',file));const uploaded=await apiJson<{files:Array<{id:string}>;errors?:Array<{message:string}>}>('/api/files',{method:'POST',body:form});supportFileIds=[...new Set([...supportFileIds,...uploaded.files.map((file)=>file.id)])];setExternalResource((current)=>({...current,supportFileIds}));setExternalFiles([]);}const result=await apiJson<{analysis:ExternalAnalysis;analysisMethod:string;sourceReadable:boolean;message:string;embedUrl:string;presentationImageUrl:string}>('/api/external-games/enrich',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sourceUrl:externalResource.sourceUrl,description:externalResource.gameDescription,supportText:externalResource.supportText,supportFileIds,selectedOutputs:externalResource.selectedOutputs})});setExternalAnalysis(result.analysis);setExternalResource((current)=>({...current,supportFileIds,embedUrl:result.embedUrl||current.embedUrl,presentationImageUrl:current.presentationImageUrl||result.presentationImageUrl||'',gameDescription:result.analysis.concepts.join('\n'),introduction:result.analysis.introduction,preGameExplanation:result.analysis.preGameExplanation,learnerTips:result.analysis.learnerTips,debrief:result.analysis.debrief,summary:result.analysis.summary,memo:result.analysis.memo,scenario:result.analysis.scenario,paper:{...current.paper,questions:result.analysis.questions}}));setExternalMessage(`${result.message} ${externalResource.provider==='wordwall'?'Le lecteur affiche uniquement l’activité Wordwall. ':''}Les champs ci-dessous restent modifiables avant validation.`);}catch(reason){setExternalError(reason instanceof Error?reason.message:'Analyse impossible. Vos informations sont conservées.');}finally{setExternalAnalyzing(false);}};

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setError('');
    if (!createActivity && !createPresentation) { setError('Choisissez au moins une création : cours et activité ou PowerPoint.'); return; }
    const requestedActivityFormats=sourceKind==='external'?externalActivityFormats(externalResource.selectedOutputs):formats;
    if (createActivity && sourceKind!=='external' && !requestedActivityFormats.length) { setError('Choisissez au moins un format d’activité.'); return; }
    if (sourceKind === 'external' && !externalResource.sourceUrl) { setError('Ajoutez un lien externe HTTPS ou un code iframe valide.'); return; }
    if (sourceKind === 'external' && !externalAnalysis) { setError('Analysez la ressource, puis vérifiez l’aperçu avant de l’ajouter au parcours.'); return; }
    if (addImages && !createActivity) { setError('Activez « Cours + activité » pour intégrer des images dans le cours.'); return; }
    if (addImages && imageSource === 'upload' && !imageFile) { setError('Choisissez une image PNG ou JPEG.'); return; }
    if (addImages && imageSource === 'document' && imageOperation !== 'document-inspired' && !imageRights) { setError('Confirmez que vous disposez des droits nécessaires pour réutiliser ce visuel.'); return; }
    setBusy(true); const form = new FormData(event.currentTarget);
    try {
      const fileIds = [...selectedFileIds,...uploadedFileIds];
      if (files.length && !uploadedFileIds.length) {
        setProgress('Transfert sécurisé des documents…'); const upload = new FormData(); files.forEach((file) => upload.append('files',file));
        const result = await apiJson<{files:Array<{id:string}>;errors?:Array<{name:string;message:string}>}>('/api/files',{method:'POST',body:upload}); const newIds = result.files.map((file) => file.id); fileIds.push(...newIds); setUploadedFileIds(newIds);
        if (result.errors?.length) setError(result.errors.map((item) => `${item.name} : ${item.message}`).join(' · '));
      }
      if (sourceKind === 'documents' && !fileIds.length) throw new Error('Importez un document ou sélectionnez-en un dans votre base privée.');
      if (fileIds.length) {
        const known = new Map(library.map((document) => [document.id,document])); const analyzedNow:string[]=[];
        for (const [index,fileId] of fileIds.entries()) {
          if (known.get(fileId)?.status === 'ready' || analyzedFileIds.includes(fileId)) continue;
          setProgress(`Analyse pédagogique complète du document ${index + 1} sur ${fileIds.length}…`);
          await apiJson(`/api/documents/${fileId}/analyze`,{method:'POST'}); analyzedNow.push(fileId);
        }
        if(analyzedNow.length)setAnalyzedFileIds((items)=>[...new Set([...items,...analyzedNow])]);
      }
      if (createActivity && requestedActivityFormats.includes('scenario') && fileIds.length && !scenarioBrief) {
        setProgress('Préremplissage du contexte, des objectifs et des contraintes…');
        const prepared = await apiJson<{projectId:string;brief:ScenarioBrief;message:string}>('/api/scenario/prepare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fileIds})});
        setScenarioBrief(prepared.brief); setProjectId(prepared.projectId); setScenarioCount(prepared.brief.recommendedSceneCount); setProgress('Cadrage prêt : vérifiez les informations ci-dessous.');
        return;
      }
      const externalContext=externalAnalysis?[`Titre : ${externalAnalysis.title}`,`Thème : ${externalAnalysis.theme}`,`Public : ${externalAnalysis.audience}`,`Objectifs : ${externalAnalysis.objectives.join(' ; ')}`,`Notions : ${externalAnalysis.concepts.join(' ; ')}`,`Consignes : ${externalAnalysis.instructions}`,`Résumé : ${externalAnalysis.summary}`,`Explications : ${externalAnalysis.preGameExplanation}`,`Éléments fournis : ${externalResource.supportText}`].join('\n'):'';
      const common: Record<string,unknown> = {prompt:sourceKind==='external'?(String(form.get('prompt')??'').trim()||`Construis les livrables sélectionnés à partir de l’analyse validée de « ${externalAnalysis?.title??'cette activité externe'} ».`):form.get('prompt'),mainFolderId:defaults?.mainFolderId,audience:scenarioBrief?.audience || externalAnalysis?.audience || form.get('audience'),level:scenarioBrief?.level || externalAnalysis?.level || form.get('level'),durationMinutes:scenarioBrief?.durationMinutes || Number(form.get('durationMinutes')),slideCount:Number(form.get('slideCount')),explanationDepth:form.get('explanationDepth'),courseLength,customPageCount,researchSources:form.get('researchSources') === 'on',sourceKind,sourceUrl:sourceKind==='external'?externalResource.sourceUrl:form.get('sourceUrl'),sourceTranscript:sourceKind==='external'?externalResource.supportText:form.get('sourceTranscript'),externalContext,externalTitle:externalAnalysis?.title,externalResource,externalAnalysis,externalOutputs:externalResource.selectedOutputs,fileIds,projectId,scenarioBrief,scenarioCount,scenarioMode:form.get('scenarioMode'),scenarioStepCount:Number(form.get('scenarioStepCount') || 1),scenarioDifficulty:form.get('scenarioDifficulty') || scenarioBrief?.recommendedDifficulty,scenarioProfession:scenarioBrief?.profession || form.get('scenarioProfession'),scenarioConstraints:scenarioBrief ? [...scenarioBrief.constraints,...scenarioBrief.risks].join(' ; ') : form.get('scenarioConstraints'),scenarioSimpleFrench:form.get('scenarioSimpleFrench') === 'on',scenarioProgressive:form.get('scenarioProgressive') === 'on',scenarioChoiceCount:Number(form.get('scenarioChoiceCount') || 3),scenarioFeedbackTiming:form.get('scenarioFeedbackTiming'),scenarioScoreMode:form.get('scenarioScoreMode'),scenarioShowHints:form.get('scenarioShowHints') === 'on',scenarioAddImages:form.get('scenarioAddImages') === 'on',scenarioOutputs:form.getAll('scenarioOutputs').map(String)};
      const messages: string[] = [];
      if (createActivity) {
        setProgress(sourceKind === 'youtube' ? 'Lecture des sous-titres ou transcription automatique de l’audio…' : sourceKind==='external'?'Création du cours, des activités et du support PDF à partir de l’analyse validée…':'Création du cours et des activités…');
        const generationFormats=requestedActivityFormats.length?requestedActivityFormats:['quiz'];
        const result = await apiJson<{activities:Array<{id:string;title:string;type:string;coursePages:GeneratedCoursePage[]}>;message:string;sourceTranscript?:string | null}>('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...common,formats:generationFormats})}); if (result.sourceTranscript) common.sourceTranscript = result.sourceTranscript; messages.push(result.message);
        if(addImages&&result.activities.length) {
          setProgress(imageSource==='ai'?'Création des illustrations pédagogiques…':imageSource==='document'?'Analyse des visuels du document…':'Intégration de votre image…');
          try { let created=0;let failed=0;for(const activity of result.activities){const outcome=await createInitialCourseImages({activityId:activity.id,coursePages:activity.coursePages,form,imageSource,imageFile,imageOperation,imageRights,imageKinds,fileIds,validated:autoValidateImages});created+=outcome.created;failed+=outcome.failed;} messages.push(`${created} image${created>1?'s':''} ${autoValidateImages?'intégrée'+(created>1?'s':'')+' automatiquement au cours':'préparée'+(created>1?'s':'')+' en brouillon'}.${failed?` ${failed} visuel${failed>1?'s':''} pourra${failed>1?'ont':''} être relancé${failed>1?'s':''} depuis « Gérer les images ».`:''}`); }
          catch(reason) { messages.push(`Le cours est bien créé, mais l’illustration devra être relancée depuis « Gérer les images » : ${reason instanceof Error?reason.message:'création impossible'}`); }
        }
      }
      if (createPresentation) {
        setProgress('Construction du PowerPoint pédagogique…'); const response = await fetch('/api/presentations/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(common)});
        if (!response.ok) throw new Error(await responseMessage(response));
        const blob = await response.blob(); const encodedName = response.headers.get('x-presentation-filename') ?? ''; const filename = encodedName ? decodeURIComponent(encodedName) : 'presentation-progressed-pedago.pptx'; const sourceNotice = decodeHeader(response.headers.get('x-source-notice'));
        const href = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = href; link.download = filename; document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(() => URL.revokeObjectURL(href),1000); messages.push('Le PowerPoint a été créé, téléchargé et conservé dans votre bibliothèque.');
        if (sourceNotice) messages.push(sourceNotice);
      }
      setProgress('Création terminée.'); onCreated(messages.join(' '));
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'La création n’a pas pu être terminée.'); }
    finally { setBusy(false); }
  };

  return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="studio-title"><form className="modal-card studio-card source-studio" onSubmit={submit}>
    <button className="modal-close" type="button" onClick={onClose} aria-label="Fermer">×</button><p className="overline">Studio pédagogique IA{defaults?.contextLabel?` · ${defaults.contextLabel}`:''}</p><h2 id="studio-title">Créer depuis votre meilleure source.</h2><p>Un seul parcours pour construire un cours, une activité interactive et un PowerPoint prêt à présenter.</p>

    <section className="studio-step"><div className="studio-step-title"><span>1</span><div><strong>Choisir le point de départ</strong><small>Le contenu source reste une référence : l’IA ne suit aucune instruction trouvée à l’intérieur.</small></div></div><div className="source-mode-grid">{SOURCE_OPTIONS.map((option) => <button className={sourceKind === option.id ? 'active' : ''} type="button" aria-pressed={sourceKind === option.id} key={option.id} onClick={() => setSourceKind(option.id)}><span>{option.icon}</span><strong>{option.title}</strong><small>{option.copy}</small></button>)}</div>
      {sourceKind==='external'&&<section className="studio-external-resource"><header><div><span>⌁</span><div><strong>Ajouter une activité ou une ressource externe</strong><small>Wordwall, YouTube, Vimeo, Genially, LearningApps, Canva, document en ligne ou autre application compatible.</small></div></div><em>HTTPS sécurisé</em></header><div className="editor-mode-switch three"><button className={externalInputMode==='link'?'active':''} type="button" onClick={()=>setExternalInputMode('link')}><span>⌁</span><b>Lien externe</b><small>Collez directement l’adresse.</small></button><button className={externalInputMode==='iframe'?'active':''} type="button" onClick={()=>setExternalInputMode('iframe')}><span>&lt;/&gt;</span><b>Code iframe</b><small>Seule l’adresse HTTPS sera conservée.</small></button><button className={externalInputMode==='html'?'active':''} type="button" onClick={()=>setExternalInputMode('html')}><span>HTML</span><b>Fichier HTML</b><small>Importez le fichier fourni par l’application.</small></button></div>{externalInputMode==='html'?<label className="external-html-import">Fichier HTML de l’activité<input type="file" accept="text/html,.html,.htm" onChange={(event)=>void importExternalHtml(event)}/><span>{externalResource.htmlSourceName?`✓ ${externalResource.htmlSourceName}`:'Choisir un fichier .html ou .htm · 2 Mo maximum'}</span><small>Le fichier n’est jamais exécuté : l’application extrait uniquement une adresse HTTPS et le texte utile.</small></label>:<label>{externalInputMode==='iframe'?'Code d’intégration iframe':'Lien HTTPS'}<textarea rows={externalInputMode==='iframe'?4:2} value={externalRaw} onChange={(event)=>acceptExternalInput(event.target.value)} placeholder={externalInputMode==='iframe'?'<iframe src="https://wordwall.net/fr/embed/…"></iframe>':'https://…'}/></label>}{externalInputMode==='html'&&externalRaw&&<label>Adresse HTTPS détectée<input value={externalRaw} readOnly/></label>}{externalResource.embedUrl&&<div className="studio-external-preview"><div><span>{providerLabel(externalResource.provider)}</span><a href={externalResource.sourceUrl} target="_blank" rel="noreferrer">Ouvrir en plein écran ↗</a></div><iframe src={externalResource.embedUrl} title="Aperçu de la ressource externe" sandbox="allow-scripts allow-forms allow-same-origin allow-popups allow-presentation" allow="fullscreen" allowFullScreen referrerPolicy="strict-origin-when-cross-origin"/></div>}<label>Courte description, texte ou transcription<textarea rows={4} value={externalResource.supportText} onChange={(event)=>setExternalResource({...externalResource,supportText:event.target.value})} placeholder="Facultatif si le contenu est lisible. Recommandé pour une ressource privée ou protégée."/></label><label className="drop-area compact">Capture, PDF ou document d’appui<input type="file" multiple accept=".pdf,.doc,.docx,.ppt,.pptx,.txt,.png,.jpg,.jpeg" onChange={(event:ChangeEvent<HTMLInputElement>)=>setExternalFiles(Array.from(event.target.files??[]))}/><span>{externalFiles.length?`${externalFiles.length} pièce(s) prête(s) pour l’analyse`:externalResource.supportFileIds.length?`${externalResource.supportFileIds.length} pièce(s) déjà importée(s)`:'Ajoutez un appui si le service bloque la lecture'}</span></label><fieldset className="external-output-picker"><legend>Contenus à générer dans cette même création · plusieurs choix possibles</legend>{EXTERNAL_OUTPUT_OPTIONS.map(([output,label])=><label key={output}><input type="checkbox" checked={externalResource.selectedOutputs.includes(output)} onChange={()=>setExternalResource({...externalResource,selectedOutputs:externalResource.selectedOutputs.includes(output)?externalResource.selectedOutputs.filter((item)=>item!==output):[...externalResource.selectedOutputs,output]})}/>{label}</label>)}</fieldset><div className="external-deliverable-note"><span>✓</span><p><strong>Une seule validation</strong>L’activité intégrée, le cours associé, les exercices sélectionnés et la version PDF A4 seront enregistrés ensemble dans votre bibliothèque.</p></div><button className="button dark analyze-external-button" type="button" disabled={externalAnalyzing||!externalResource.sourceUrl} onClick={()=>void analyzeExternal()}>{externalAnalyzing?'Analyse en cours…':'✦ Analyser cette ressource'}</button>{externalError&&<p className="form-message error" role="status">{externalError}</p>}{externalMessage&&<p className="form-message" role="status">{externalMessage}</p>}{externalAnalysis&&<div className="external-analysis-review"><header><div><strong>Aperçu de l’analyse · à vérifier</strong><small>Modifiez librement les informations avant la création définitive.</small></div><span>Prêt à valider</span></header><div className="form-row"><label>Titre<input value={externalAnalysis.title} onChange={(event)=>updateExternalAnalysis({title:event.target.value})}/></label><label>Thème<input value={externalAnalysis.theme} onChange={(event)=>updateExternalAnalysis({theme:event.target.value})}/></label><label>Niveau<select value={externalAnalysis.level} onChange={(event)=>updateExternalAnalysis({level:event.target.value as ExternalAnalysis['level']})}><option value="debutant">Débutant</option><option value="intermediaire">Intermédiaire</option><option value="avance">Avancé</option></select></label></div><label>Public concerné<input value={externalAnalysis.audience} onChange={(event)=>updateExternalAnalysis({audience:event.target.value})}/></label><div className="form-row two"><label>Objectifs pédagogiques<textarea rows={4} value={externalAnalysis.objectives.join('\n')} onChange={(event)=>updateExternalAnalysis({objectives:event.target.value.split('\n').map((item)=>item.trim()).filter(Boolean)})}/></label><label>Notions abordées<textarea rows={4} value={externalAnalysis.concepts.join('\n')} onChange={(event)=>updateExternalAnalysis({concepts:event.target.value.split('\n').map((item)=>item.trim()).filter(Boolean)})}/></label></div><label>Consignes<textarea rows={3} value={externalAnalysis.instructions} onChange={(event)=>updateExternalAnalysis({instructions:event.target.value})}/></label><div className="form-row two"><label>Explications<textarea rows={5} value={externalAnalysis.preGameExplanation} onChange={(event)=>updateExternalAnalysis({preGameExplanation:event.target.value})}/></label><label>Résumé<textarea rows={5} value={externalAnalysis.summary} onChange={(event)=>updateExternalAnalysis({summary:event.target.value})}/></label></div><details><summary>Relire les questions et les réponses</summary>{externalAnalysis.questions.map((question,index)=><div className="external-analysis-question" key={index}><input value={question.question} onChange={(event)=>updateExternalAnalysis({questions:externalAnalysis.questions.map((item,itemIndex)=>itemIndex===index?{...item,question:event.target.value}:item)})}/><input value={question.answer} onChange={(event)=>updateExternalAnalysis({questions:externalAnalysis.questions.map((item,itemIndex)=>itemIndex===index?{...item,answer:event.target.value}:item)})}/></div>)}</details></div>}</section>}
      {(sourceKind === 'youtube' || sourceKind === 'web') && <label>{sourceKind === 'youtube' ? 'Lien YouTube, Vimeo ou fichier vidéo/audio public' : 'Lien de la page extérieure'}<input name="sourceUrl" type="url" required placeholder={sourceKind === 'youtube' ? 'https://www.youtube.com/watch?v=… ou https://…/video.mp4' : 'https://www.exemple.fr/ressource'} /></label>}
      {sourceKind === 'youtube' && <><div className="automatic-analysis-note"><span>✓</span><div><strong>Le lien reste validable même si YouTube restreint l’audio</strong><small>L’application utilise les sous-titres ou transcrit la piste publique. Si YouTube les bloque, elle poursuit avec le titre, la description et les aperçus visuels disponibles, puis signale que l’analyse est partielle.</small></div></div><details className="transcript-option"><summary>J’ai déjà une transcription — facultatif</summary><label>Transcription ou texte alternatif<textarea name="sourceTranscript" rows={5} placeholder="Vous pouvez la coller pour obtenir une analyse complète lorsque la vidéo est privée ou protégée." /></label></details></>}
      <label>Votre consigne pédagogique {sourceKind === 'prompt' ? '' : '(facultative)'}<textarea name="prompt" rows={4} required={sourceKind === 'prompt'} defaultValue={defaults?.prompt??''} placeholder="Ex. Construis une formation progressive, avec des exemples métier et une évaluation adaptée à des débutants." /></label>
      <div className="form-row"><label>Public concerné<input name="audience" placeholder="Agents de propreté débutants" /></label><label>Niveau<select name="level"><option value="debutant">Débutant</option><option value="intermediaire">Intermédiaire</option><option value="avance">Avancé</option></select></label><label>Durée du cours<input name="durationMinutes" type="number" min="1" max="480" defaultValue="30" /></label></div>
      <label className={`drop-area ${sourceKind === 'documents' ? 'active-source' : ''}`}>Importer de nouveaux documents {sourceKind === 'documents' ? '' : 'complémentaires'}<input type="file" multiple accept=".pdf,.docx,.ppt,.pptx,.txt,.png,.jpg,.jpeg" onChange={(event) => { setFiles(Array.from(event.target.files ?? [])); setUploadedFileIds([]); resetPreparation(); }} /><span>{files.length ? `${files.length} fichier(s) sélectionné(s)` : 'PDF, Word, PowerPoint, texte ou image · 20 Mo maximum par fichier'}</span></label>
      {library.length > 0 && <div className="studio-document-library"><header><div><strong>Ou réutiliser ma base documentaire</strong><small>Les fichiers déjà analysés ne sont pas renvoyés une seconde fois.</small></div><span>{selectedFileIds.length} sélectionné(s)</span></header><div>{library.map((document) => <label className={selectedFileIds.includes(document.id) ? 'selected' : ''} key={document.id}><input type="checkbox" checked={selectedFileIds.includes(document.id)} onChange={() => { setSelectedFileIds((items) => items.includes(document.id) ? items.filter((id) => id !== document.id) : [...items,document.id]); resetPreparation(); }} /><span>▤</span><div><strong>{document.originalName}</strong><small>{document.status === 'ready' ? `Prêt${document.pageCount ? ` · ${document.pageCount} page(s)` : ''}${document.detectedTheme ? ` · ${document.detectedTheme}` : ''}` : document.status === 'failed' ? 'Analyse à relancer automatiquement' : 'Sera analysé avant la préparation'}</small></div></label>)}</div></div>}
    </section>

    <section className="studio-step"><div className="studio-step-title"><span>2</span><div><strong>Choisir les livrables</strong><small>Vous pouvez produire l’activité, le PowerPoint, ou les deux en une seule demande.</small></div></div><div className="output-choice-grid"><label className={createActivity ? 'selected' : ''}><input type="checkbox" checked={createActivity} onChange={(event) => setCreateActivity(event.target.checked)} /><span>?</span><strong>Cours + activité</strong><small>Mini-cours, jeu, réponses et corrigé A4</small></label><label className={createPresentation ? 'selected' : ''}><input type="checkbox" checked={createPresentation} onChange={(event) => setCreatePresentation(event.target.checked)} /><span>▣</span><strong>PowerPoint</strong><small>Fichier .pptx structuré et téléchargeable</small></label></div>
      {createActivity && sourceKind!=='external' && <fieldset><legend>Format de l’activité</legend><div className="format-checks">{CREATABLE_ACTIVITY_TYPES.map(([type,title]) => <label key={type}><input type="checkbox" checked={formats.includes(type)} onChange={() => setFormats((items) => items.includes(type) ? items.filter((item) => item !== type) : [...items,type])} />{title}</label>)}</div></fieldset>}
      {createActivity && (sourceKind==='external'?externalActivityFormats(externalResource.selectedOutputs):formats).includes('scenario') && <fieldset className="scenario-ai-options"><legend>Paramètres de la mise en situation</legend><div className="form-row"><label>Type de parcours<select name="scenarioMode" defaultValue="progressive" onChange={(event) => setScenarioCount(event.target.value === 'single' ? 1 : Math.max(3,scenarioCount))}><option value="single">Une seule mise en situation</option><option value="independent">Plusieurs situations indépendantes</option><option value="progressive">Parcours progressif</option><option value="successive">Décisions successives</option><option value="case-study">Étude de cas</option><option value="final-assessment">Évaluation finale</option></select></label><label>Nombre de situations<select name="scenarioCount" value={scenarioCount} onChange={(event) => setScenarioCount(Number(event.target.value))}><option value="1">1 situation</option><option value="2">2 situations</option><option value="3">3 situations</option><option value="4">4 situations</option><option value="5">5 situations</option><option value="6">6 situations</option></select></label><label>Étapes par situation<select name="scenarioStepCount" defaultValue="1"><option value="1">1 décision</option><option value="2">2 décisions</option><option value="3">3 décisions</option></select></label></div><div className="form-row"><label>Difficulté<select name="scenarioDifficulty" defaultValue={scenarioBrief?.recommendedDifficulty ?? 'progressive'}><option value="simple">Simple</option><option value="progressive">Progressive</option><option value="complexe">Complexe</option></select></label><label>Métier ou secteur<input name="scenarioProfession" placeholder="Ex. Agent de bio-nettoyage en EHPAD" /></label></div><label>Contraintes professionnelles à intégrer<textarea name="scenarioConstraints" rows={3} placeholder="Ex. consentement du résident, planning chargé, transmission à l’encadrant, protocole de l’établissement" /></label><div className="form-row"><label>Décisions par scène<select name="scenarioChoiceCount" defaultValue="3"><option value="3">3 décisions</option><option value="4">4 décisions</option></select></label><label>Afficher le feedback<select name="scenarioFeedbackTiming" defaultValue="immediate"><option value="immediate">Après chaque décision</option><option value="deferred">Au bilan final</option></select></label><label>Mode de score<select name="scenarioScoreMode" defaultValue="points"><option value="points">Points visibles</option><option value="skills">Compétences</option><option value="hidden">Score masqué</option></select></label></div><div className="scenario-ai-checks"><label><input name="scenarioProgressive" type="checkbox" defaultChecked />Progression reliée</label><label><input name="scenarioSimpleFrench" type="checkbox" defaultChecked />Français simplifié</label><label><input name="scenarioShowHints" type="checkbox" />Afficher les indices</label><label><input name="scenarioAddImages" type="checkbox" />Prévoir des illustrations</label></div><div className="scenario-output-checks"><strong>Versions préparées</strong><label><input name="scenarioOutputs" value="digital" type="checkbox" defaultChecked />Numérique</label><label><input name="scenarioOutputs" value="a4" type="checkbox" defaultChecked />PDF / impression A4</label><label><input name="scenarioOutputs" value="learner" type="checkbox" defaultChecked />Apprenant</label><label><input name="scenarioOutputs" value="trainer" type="checkbox" defaultChecked />Corrigé formateur</label></div></fieldset>}
      {scenarioBrief && <ScenarioBriefEditor value={scenarioBrief} onChange={setScenarioBrief} />}
      {createPresentation && <label>Nombre indicatif de diapositives<select name="slideCount" defaultValue="10"><option value="7">Court · environ 7 diapositives</option><option value="10">Standard · environ 10 diapositives</option><option value="14">Approfondi · environ 14 diapositives</option><option value="18">Complet · environ 18 diapositives</option></select></label>}
      {createActivity&&(sourceKind==='documents'||sourceKind==='external'&&externalResource.selectedOutputs.includes('course'))&&<div className="course-length-options"><div><strong>{sourceKind==='external'?'Longueur du cours associé':'Longueur du cours issu du PDF'}</strong><small>{sourceKind==='external'?'L’analyse validée sera répartie en un cours progressif et structuré.':'Le document sera analysé page par page puis réparti en chapitres.'}</small></div><label>Format<select value={courseLength} onChange={(event)=>setCourseLength(event.target.value as CourseLength)}><option value="short">Cours court · 4 pages</option><option value="intermediate">Cours intermédiaire · 7 pages</option><option value="complete">Cours complet et détaillé · 12 pages</option><option value="custom">Nombre de pages personnalisé</option></select></label>{courseLength==='custom'&&<label>Nombre de pages<input type="number" min="4" max="24" value={customPageCount} onChange={(event)=>setCustomPageCount(Math.min(24,Math.max(4,Number(event.target.value)||4)))}/></label>}</div>}
      <div className="generation-options"><label><span>Profondeur du cours et des explications</span><select name="explanationDepth" defaultValue="detailed"><option value="detailed">Détaillé — cours complet, exemples et mémo</option><option value="essential">Essentiel — notions clés et corrections</option><option value="none">Sans mini-cours — corrections courtes</option></select></label><label className="check-line"><input name="researchSources" type="checkbox" />Compléter avec une recherche de sources institutionnelles fiables</label></div>
    </section>
    {createActivity&&<section className="studio-step image-studio-step"><div className="studio-step-title"><span>3</span><div><strong>Illustrer le cours</strong><small>Les visuels apparaissent dans le cours numérique, le plein écran et le PDF A4.</small></div></div><label className="image-feature-toggle"><input type="checkbox" checked={addImages} onChange={(event)=>setAddImages(event.target.checked)}/><span><strong>Ajouter automatiquement des images au cours</strong><small>Activé par défaut · plusieurs pages seront illustrées selon leur contenu.</small></span></label>{addImages&&<><label className="check-line"><input type="checkbox" checked={autoValidateImages} onChange={(event)=>setAutoValidateImages(event.target.checked)}/>Intégrer immédiatement les visuels générés. Décochez pour les conserver en brouillon avant validation.</label><div className="image-source-switch studio-image-sources"><button className={imageSource==='upload'?'active':''} type="button" onClick={()=>setImageSource('upload')}>↑ Importer mon image</button><button className={imageSource==='ai'?'active':''} type="button" onClick={()=>setImageSource('ai')}>✦ Générer avec l’IA</button><button className={imageSource==='document'?'active':''} type="button" onClick={()=>setImageSource('document')}>▤ Visuel d’un document</button></div>
      {imageSource==='upload'&&<label className="drop-area">Image personnelle PNG ou JPEG<input type="file" accept="image/png,image/jpeg" onChange={(event)=>setImageFile(event.target.files?.[0]??null)}/><span>{imageFile?.name??'10 Mo maximum'}</span></label>}
      {imageSource==='document'&&<><div className="form-row two"><label>Document à analyser<select name="imageSourceFileId" defaultValue={selectedFileIds[0]??''}><option value="">Premier document sélectionné ou importé</option>{library.filter((document)=>selectedFileIds.includes(document.id)).map((document)=><option value={document.id} key={document.id}>{document.originalName}</option>)}</select></label><label>Page à privilégier<input name="imageSourcePage" type="number" min="1" placeholder="L’IA choisit"/></label></div><div className="document-image-actions"><label><input type="radio" checked={imageOperation==='document-use'} onChange={()=>setImageOperation('document-use')}/>Utiliser directement si j’en possède les droits</label><label><input type="radio" checked={imageOperation==='document-crop'} onChange={()=>setImageOperation('document-crop')}/>Recadrer</label><label><input type="radio" checked={imageOperation==='document-inspired'} onChange={()=>setImageOperation('document-inspired')}/>Créer une illustration originale inspirée</label></div>{imageOperation!=='document-inspired'&&<label className="check-line"><input type="checkbox" checked={imageRights} onChange={(event)=>setImageRights(event.target.checked)}/>Je confirme disposer des droits nécessaires pour réutiliser ce visuel.</label>}<p className="copyright-note">En mode inspiré, l’IA transmet la même idée pédagogique avec une composition et un graphisme nouveaux, sans copie exacte.</p></>}
      <div className="form-row two"><label>Style de l’image<select name="imageStyle" defaultValue="automatic">{COURSE_IMAGE_STYLES.map((value)=><option value={value} key={value}>{COURSE_IMAGE_STYLE_LABELS[value]}</option>)}</select></label><label>Texte alternatif<input name="imageAltText" placeholder="Ex. Agent préparant son matériel de bionettoyage"/></label></div><label>Consigne visuelle<textarea name="imagePrompt" rows={3} placeholder="Ex. Montrer clairement les bons gestes et le matériel, avec un environnement professionnel réaliste et un cadrage lisible."/></label><fieldset className="image-placement-checks"><legend>Visuels souhaités · plusieurs choix possibles</legend>{IMAGE_KIND_OPTIONS.map(([kind,label])=><label key={kind}><input type="checkbox" checked={imageKinds.includes(kind)} onChange={()=>setImageKinds((items)=>kind==='automatic'?[kind]:items.includes(kind)?items.filter((item)=>item!==kind):[...items.filter((item)=>item!=='automatic'),kind].slice(0,6))}/>{label}</label>)}</fieldset></>}
    </section>}
    {progress && <div className="progress-message" role="status">{progress}</div>}{error && <div className="form-message error" role="status">{error}</div>}
    <div className="modal-actions studio-actions"><button className="button light" type="button" onClick={onClose}>Annuler</button><button className="button dark" type="submit" disabled={busy}>{busy ? 'Traitement en cours…' : sourceKind==='external'&&externalAnalysis?'Valider et ajouter au parcours':createActivity && (sourceKind==='external'?externalActivityFormats(externalResource.selectedOutputs):formats).includes('scenario') && (files.length || selectedFileIds.length || uploadedFileIds.length) && !scenarioBrief ? 'Analyser et préparer la mise en situation' : scenarioBrief ? 'Valider et construire le parcours' : 'Créer les livrables'}</button></div>
  </form></div>;
}

function ScenarioBriefEditor({value,onChange}:{value:ScenarioBrief;onChange:(value:ScenarioBrief)=>void}) {
  const field = (key:keyof ScenarioBrief,next:unknown) => onChange({...value,[key]:next});
  return <fieldset className="scenario-brief-review"><legend>Cadrage prérempli — à vérifier</legend><div className="scenario-brief-banner"><span>✓</span><div><strong>L’analyse page par page est terminée</strong><small>Vous gardez la décision finale. Modifiez toute information avant la génération du parcours.</small></div></div><div className="form-row"><label>Titre<input value={value.title} onChange={(event) => field('title',event.target.value)} /></label><label>Thème<input value={value.theme} onChange={(event) => field('theme',event.target.value)} /></label><label>Sous-thème<input value={value.subtheme} onChange={(event) => field('subtheme',event.target.value)} /></label></div><div className="form-row"><label>Public<input value={value.audience} onChange={(event) => field('audience',event.target.value)} /></label><label>Métier<input value={value.profession} onChange={(event) => field('profession',event.target.value)} /></label><label>Rôle de l’apprenant<input value={value.learnerRole} onChange={(event) => field('learnerRole',event.target.value)} /></label></div><div className="form-row"><label>Niveau<select value={value.level} onChange={(event) => field('level',event.target.value)}><option value="debutant">Débutant</option><option value="intermediaire">Intermédiaire</option><option value="avance">Avancé</option></select></label><label>Durée estimée<input type="number" min="5" max="480" value={value.durationMinutes} onChange={(event) => field('durationMinutes',Number(event.target.value))} /></label><label>Difficulté conseillée<input value={value.recommendedDifficulty} readOnly /></label></div><label>Contexte professionnel<textarea rows={3} value={value.professionalContext} onChange={(event) => field('professionalContext',event.target.value)} /></label><label>But d’apprentissage<textarea rows={2} value={value.learningGoal} onChange={(event) => field('learningGoal',event.target.value)} /></label><div className="form-row"><BriefList label="Prérequis" value={value.prerequisites} onChange={(items) => field('prerequisites',items)} /><BriefList label="Objectifs pédagogiques" value={value.objectives} onChange={(items) => field('objectives',items)} /><BriefList label="Compétences travaillées" value={value.competencies} onChange={(items) => field('competencies',items)} /></div><div className="form-row"><BriefList label="Vocabulaire important" value={value.vocabulary} onChange={(items) => field('vocabulary',items)} /><BriefList label="Contraintes" value={value.constraints} onChange={(items) => field('constraints',items)} /><BriefList label="Risques et points de vigilance" value={value.risks} onChange={(items) => field('risks',items)} /></div><div className="form-row"><BriefList label="Procédures clés détectées" value={value.keyProcedures} onChange={(items) => field('keyProcedures',items)} /><BriefList label="Critères de réussite" value={value.successCriteria} onChange={(items) => field('successCriteria',items)} /></div></fieldset>;
}
function BriefList({label,value,onChange}:{label:string;value:string[];onChange:(value:string[])=>void}) { return <label>{label}<textarea rows={4} value={value.join('\n')} onChange={(event) => onChange(event.target.value.split('\n').map((item) => item.trim()).filter(Boolean))} /></label>; }

async function createInitialCourseImages({activityId,coursePages,form,imageSource,imageFile,imageOperation,imageRights,imageKinds,fileIds,validated}:{activityId:string;coursePages:GeneratedCoursePage[];form:FormData;imageSource:'upload'|'ai'|'document';imageFile:File|null;imageOperation:'document-use'|'document-crop'|'document-inspired';imageRights:boolean;imageKinds:string[];fileIds:string[];validated:boolean}) {
  const selected=imageKinds.length?imageKinds:['automatic'];
  const fallbackPages:GeneratedCoursePage[]=[{id:'',title:'Couverture du cours',kind:'cover',lead:''},{id:'',title:'Notion centrale',kind:'chapter',lead:''},{id:'',title:'Mise en pratique',kind:'exercises',lead:''}];
  const pages=coursePages.length?coursePages:fallbackPages;
  const automaticPages=[pages.find((page)=>page.kind==='cover'),pages.find((page)=>page.kind==='introduction'),...pages.filter((page)=>page.kind==='chapter').slice(0,3),pages.find((page)=>page.kind==='exercises')??pages.find((page)=>page.kind==='synthesis')].filter((page,index,items):page is GeneratedCoursePage=>Boolean(page)&&items.indexOf(page)===index).slice(0,6);
  const automaticPlans=automaticPages.map((page,index)=>({page,placement:placementForPage(page,index),style:page.kind==='chapter'?'pedagogical':page.kind==='exercises'?'illustration':'automatic',hint:hintForPage(page)}));
  const plans=(selected.includes('automatic')?automaticPlans:selected.map((kind,index)=>{const page=pageForImageKind(pages,kind,index);return {page,placement:kind==='cover'?'cover':kind==='realistic'?'explanation':kind==='illustration'?'introduction':kind==='diagram'?'procedure':kind==='example'?'example':'exercise',style:kind==='realistic'?'realistic':kind==='illustration'?'illustration':kind==='diagram'||kind==='exercise'?'pedagogical':'automatic',hint:kind==='cover'?'couverture':kind==='realistic'?'situation professionnelle réaliste':kind==='illustration'?'illustration pédagogique':kind==='diagram'?'schéma explicatif clair':kind==='example'?'exemple professionnel':'exercice ou quiz'};})).slice(0,imageSource==='upload'?1:6);
  let created=0;let failed=0;
  for(const plan of plans) {
    const requestedStyle=String(form.get('imageStyle')??'automatic'); const style=plan.style==='automatic'?requestedStyle:plan.style; const pageContext=[plan.page.title,plan.page.lead].filter(Boolean).join(' — '); const prompt=[String(form.get('imagePrompt')??''),`Illustrer précisément cette partie du cours : ${pageContext}.`,`Usage souhaité : ${plan.hint}. Sans texte illisible, composition claire pour un public adulte en formation professionnelle.`].filter(Boolean).join('\n');
    try {
      if(imageSource==='upload') {
        if(!imageFile) throw new Error('Choisissez une image PNG ou JPEG.'); const upload=new FormData(); upload.set('activityId',activityId); upload.set('mode','upload'); upload.set('placement',plan.placement); upload.set('pageId',plan.page.id); upload.set('style',style); upload.set('prompt',prompt); upload.set('altText',String(form.get('imageAltText')??'')||`Illustration de ${plan.page.title}`); upload.set('validated',String(validated)); upload.set('file',imageFile); await apiJson('/api/course-images',{method:'POST',body:upload});
      } else {
        const sourceFileId=String(form.get('imageSourceFileId')??'')||fileIds[0]||''; if(imageSource==='document'&&!sourceFileId) throw new Error('Sélectionnez un document source.');
        await apiJson('/api/course-images',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({activityId,mode:imageSource==='ai'?'ai':imageOperation,placement:plan.placement,pageId:plan.page.id,style,prompt,altText:String(form.get('imageAltText')??'')||`Illustration de ${plan.page.title}`,sourceFileId,sourcePage:Number(form.get('imageSourcePage')||0),rightsConfirmed:imageRights,validated})});
      }
      created++;
    } catch { failed++; }
  }
  return {created,failed};
}

function placementForPage(page:GeneratedCoursePage,index:number) { if(page.kind==='cover')return 'cover';if(page.kind==='introduction')return 'introduction';if(page.kind==='synthesis')return 'synthesis';if(page.kind==='exercises')return 'exercise';return index%3===0?'procedure':index%2===0?'example':'explanation'; }
function hintForPage(page:GeneratedCoursePage) { return page.kind==='cover'?'visuel de couverture':page.kind==='introduction'?'mise en contexte du cours':page.kind==='synthesis'?'synthèse visuelle':page.kind==='exercises'?'activité d’application ou quiz':'explication visuelle de la leçon'; }
function pageForImageKind(pages:GeneratedCoursePage[],kind:string,index:number) { const chapters=pages.filter((page)=>page.kind==='chapter');if(kind==='cover')return pages.find((page)=>page.kind==='cover')??pages[0]!;if(kind==='illustration')return pages.find((page)=>page.kind==='introduction')??chapters[0]??pages[0]!;if(kind==='exercise')return pages.find((page)=>page.kind==='exercises')??pages.at(-1)!;return chapters[index%Math.max(1,chapters.length)]??pages.find((page)=>page.kind!=='cover')??pages[0]!; }
function externalActivityFormats(outputs:ExternalResourceOutput[]):ActivityType[] { const formats:ActivityType[]=[];if(outputs.includes('quiz'))formats.push('quiz');if(outputs.includes('true-false'))formats.push('true-false');if(outputs.includes('scenario')||outputs.includes('case-study'))formats.push('scenario');if(outputs.includes('exercise'))formats.push('drag-drop');return [...new Set(formats)]; }

async function apiJson<T>(url: string,options?: RequestInit): Promise<T> { const response = await fetch(url,options); const payload = await response.json() as ApiEnvelope<T>; if (!payload.ok) throw new Error(payload.error.message); return payload.data; }
async function responseMessage(response: Response): Promise<string> { try { const payload = await response.json() as ApiEnvelope<unknown>; return payload.ok ? 'Création impossible.' : payload.error.message; } catch { return 'La création du PowerPoint a échoué.'; } }
function decodeHeader(value: string | null): string { if (!value) return ''; try { return decodeURIComponent(value); } catch { return ''; } }
